; wCFE6/wCFE7 = monster id: copies its 26-byte MonsterTable record to wCFEC (ids at or above $250 come from bank $A2 through Func_0A2_402D)
; 20 call sites from 20 routines (e.g. DebugShowMonsterRecord, CreateMonsterRecordOfKindHFFC7_Sub01_Sub01, GameMode5_Update_Case01_Case06_Case06_Sub01, ScriptCommandF3_Run_Case05_Case0E_Sub01, ...)
; points at: wRecordBuffer
LoadMonsterRecord::
Func_034_4001:: ; address name
    ld de, wRecordBuffer
    call LoadMonsterRecordTo
    ret

; copies hFFC6 bytes of the 26-byte entry of monster wMonsterId/wCFE7 plus C from $4075 to DE; ids from $250 use CopyMonsterTableBytesFrom4056 in bank $A2 (E-0125)
; 2 call sites from 2 routines (e.g. LoadEncounterMonsterIdsToWD09D, Func_085_5B53)
; reads: wCFE7, wMonsterId, hFFC6
CopyMonsterTableBytesFrom4075::
Func_034_4008:: ; address name
    ld a, [wCFE7]
    cp a, $02
    jr c, Jump_034_401D
    ld a, [wMonsterId]
    cp a, $50
    jr c, Jump_034_401D
    farcall CopyMonsterTableBytesFrom4056
    ret

Jump_034_401D::
    push de
    push bc
    ld a, [wMonsterId]
    ld c, a
    ld a, [wCFE7]
    ld b, a
    ld a, $1A
    call Multiply8By16
    ld a, l
    add a, $75
    ld l, a
    ld a, h
    adc a, $40
    ld h, a
    pop bc
    ld b, $00
    add hl, bc
    ldh a, [hFFC6]
    ld b, a
    pop de
    call CopyBytesDEFromHL
    ret

; DE = destination: like LoadMonsterRecord but copies the 26-byte record to [DE]
; 1 call site from 1 routine (e.g. LoadMonsterRecord)
; reads: wCFE7, wMonsterId
LoadMonsterRecordTo::
Func_034_4040:: ; address name
    ld a, [wCFE7]
    cp a, $02
    jr c, Jump_034_4055
    ld a, [wMonsterId]
    cp a, $50
    jr c, Jump_034_4055
    farcall LoadMonsterRecordTo_Sub01
    ret

Jump_034_4055::
    push de
    ld a, [wMonsterId]
    ld c, a
    ld a, [wCFE7]
    ld b, a
    ld a, $1A
    call Multiply8By16
    ld a, l
    add a, $75
    ld l, a
    ld a, h
    adc a, $40
    ld h, a
    pop de
    ld b, $1A

; B bytes from [HL] to [DE]; HL and DE advance
; 1 call site from 1 routine (e.g. CopyMonsterTableBytesFrom4075)
CopyBytesDEFromHL::
Func_034_406E:: ; address name
    ld a, [hl+]
    ld [de], a
    inc de
    dec b
    jr nz, CopyBytesDEFromHL
    ret

; E-0033 (C1: LoadMonsterRecord copies a 26-byte record from here by 16-bit id (wCFE6/wCFE7); ids at or above $250 use bank $A2 instead, so this table has 592 records; record 1 holds 25, 0, 10, 7, 8, 7 and then $C8 $C8 $64 $C8, exactly the values the opening monster's save record shows for its HP, MP, ATK, DEF, AGL, INT and next four bytes; the order of the six stat words is confirmed by the pause menu's INFO panel, E-0046). Skill ids stay below 175 (one record, id 88, has $C8 in the fourth slot). Bytes 22-25 equal the save record's bytes at offsets $6F-$72 for the opening monster (E-0034); the three used by PersonalityIndexOfRecord are the personality axes. The first word is the picture number (E-0041): drawing the pictures it names gave a slime for monster 1 ('Slime'), another slime for monster 2 ('SpotSlime') and a spiky ball for monster 3 ('CactiBall'); monster names are the strings of bank $88 (category = id >> 8, index = id & $FF).
; record: picture number: index into MonsterPictureTable, MonsterAttributeMapTable and MonsterPaletteTable (at most $0179; ids 1, 2, 3 = Slime, SpotSlime, CactiBall use pictures 10, 2, 145); skill id 1 (SkillTable index, $FF = none); skill id 2; skill id 3; skill id 4; 16-bit value, up to $E8EE (meaning not established); byte 8, values 0-7; byte 9, values 0-99; base HP; base MP; base ATK; base DEF; base AGL; base INT; byte 22: personality axis copied to save-record offset $6F (graded with weight 9 by PersonalityIndexOfRecord); byte 23: personality axis copied to offset $70 (weight 1); byte 24: copied to offset $71 (not used by PersonalityIndexOfRecord); byte 25: personality axis copied to offset $72 (weight 3)
